import {FOODS, RECIPES, calculateTargets, buildWorkout} from './data.js';
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={leaf:'M20 4C10 2 3 6 4 13c1 7 10 9 14 3 2-3 2-8 2-12ZM5 19 16 8M9 14v-4m4 0h4',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M4 3h13a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3m-3 15a3 3 0 0 1 3-3h14M8 7h7M8 11h5',utensils:'M4 3v5a3 3 0 0 0 6 0V3M7 3v18M20 21V3c-5 2-6 8 0 9',dumbbell:'m4 7 3-3 13 13-3 3ZM2 8l6-6M16 22l6-6M2 5l3-3M19 22l3-3',chart:'M4 3v17h17M8 14l4-5 4 3 5-8',help:'M12 17h.01M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M4 12h16m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',target:'M22 12a10 10 0 1 1-5-8M18 12a6 6 0 1 1-6-6M12 12l9-9m-5 0h5v5',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 2',flame:'M12 3c1 5 7 7 7 12a7 7 0 0 1-14 0c0-3 2-6 4-7 0 4 3 4 3-5Z',drop:'M12 2C9 7 4 11 4 16a8 8 0 0 0 16 0c0-5-5-9-8-14Z',glass:'M5 3h14l-2 18H7ZM6 11h12',sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',sunrise:'M3 17h18M5 21h14M7 17a5 5 0 0 1 10 0M12 3v5m-7 2 2 2m12-2-2 2',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z',apple:'M12 6C8 2 2 7 4 13c3 11 5 6 8 7 3-1 5 4 8-7 2-6-4-11-8-7Zm0 0c0-3 2-4 4-4',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 9h18c0-1-3-1-3-9M10 21h4',check:'m5 12 4 4L20 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',menu:'M3 6h18M3 12h18M3 18h18',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 11h16',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 3 11 8 15 5-4 13-10 8-15Z',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M3 8l3-4 3 1 3-3 3 3 3-1 3 4-2 3 2 3-3 5-3-1-3 3-3-3-3 1-3-5 2-3Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',back:'M20 12H4m5-5-5 5 5 5'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const athlete=()=>`<svg width="210" height="105" viewBox="0 0 260 130" fill="none" aria-hidden="true"><ellipse cx="132" cy="113" rx="107" ry="5" fill="#cad6bb"/><path d="M31 113h205" stroke="#a2b48c" stroke-width="2"/><circle cx="75" cy="46" r="12" fill="#5d7752"/><path d="m86 58 50 22 45 4" stroke="#55734a" stroke-width="18" stroke-linecap="round"/><path d="m94 63-18 24-11 21" stroke="#69835c" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/><path d="m113 70-15 20-2 20" stroke="#55734a" stroke-width="10" stroke-linecap="round"/><path d="m177 85 21 24h21" stroke="#69835c" stroke-width="11" stroke-linecap="round"/><path d="m143 82 24 26h22" stroke="#55734a" stroke-width="12" stroke-linecap="round"/><path d="M68 109h-14m44 1h-10" stroke="#435e3a" stroke-width="5" stroke-linecap="round"/></svg>`;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const uid=()=>crypto.randomUUID();const format=n=>Math.round(n).toLocaleString();const goalNames={lose:'Lose body fat',gain:'Build muscle',maintain:'Maintain balance'};
const seedLogs=[{id:'sample1',name:'Berry overnight oats',meal:'Breakfast',calories:420,protein:28,carbs:60,fat:8,portion:'1 serving',date:today(),sample:true},{id:'sample2',name:'Lemon herb chicken bowl',meal:'Lunch',calories:510,protein:48,carbs:42,fat:17,portion:'1 serving',date:today(),sample:true},{id:'sample3',name:'Greek yogurt, banana & almonds',meal:'Snacks',calories:310,protein:20,carbs:35,fat:11,portion:'1 bowl',date:today(),sample:true}];
let state;try{state=JSON.parse(localStorage.getItem('nourish-v1'))}catch{}state=state&&Array.isArray(state.logs)?state:{profile:null,logs:seedLogs,water:{[today()]:3},weights:[],sessions:[],customFoods:[],sample:true};
state.water??={};state.weights??=[];state.sessions??=[];state.customFoods??=[];
let page='today',diaryDate=today(),recipeFilter='All recipes',recipeQuery='',budget=5,modalReturnFocus=null,session=null,restTimer=null,foodMeal='Breakfast',foodResults=FOODS,foodQuery='',foodTab='catalog',selectedFood=null;
const defaults={name:'Your space',goal:'lose',experience:'beginner',limitations:[]};
const profile=()=>state.profile||defaults;const targets=()=>{try{return state.profile?calculateTargets(state.profile):{calories:2100,protein:140,carbs:230,fat:70}}catch{return {calories:2100,protein:140,carbs:230,fat:70}}};
const workout=()=>{const w=buildWorkout(profile());if((profile().limitations||[]).includes('shoulder'))return {...w,isRecovery:true,title:'Shoulder protection & guided recovery',exercises:[],duration:0,note:'Shoulder injury selected. Automated upper-body and full-body sessions are paused pending clinician clearance. Use the guidance below and ask about safe lower-body activity.'};return w};
const save=()=>{try{localStorage.setItem('nourish-v1',JSON.stringify(state))}catch{toast('Storage is unavailable. Your changes will last for this visit.')}};
const totals=(date=today())=>state.logs.filter(l=>l.date===date).reduce((a,l)=>{for(const k of ['calories','protein','carbs','fat'])a[k]+=Number(l[k])||0;return a},{calories:0,protein:0,carbs:0,fat:0});
let toastTimeout;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const mealIcons={Breakfast:'sunrise',Lunch:'sun',Dinner:'moon',Snacks:'apple'};
function navigation(){return `<aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('leaf',33)}</span>nourish<span style="color:#98ac7e">.</span></div><div class="workspace-label">YOUR EVERYDAY</div><nav class="nav" aria-label="Main navigation">${[['today','grid','Overview'],['diary','book','Food Diary'],['recipes','utensils','Recipes'],['training','dumbbell','Training'],['progress','chart','Progress']].map(([id,i,n])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i,18)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-motto"><div class="mini-icon">${icon('leaf',17)}</div><strong>Small steps. Stronger you.</strong><p>A little consistency goes a long way. You’ve got this.</p></div><button class="help-button" data-action="about">${icon('help',17)}Help & information</button><button class="profile-button" data-action="goals"><span class="avatar">${esc(state.profile?.name?.slice(0,2).toUpperCase()||'YO')}</span><span><strong>${esc(state.profile?.name||'Your personal space')}</strong><small>${state.profile?'Your plan, your pace':'Let’s make it yours'}</small></span>${icon('down',13)}</button></div></aside><div class="mobile-overlay"></div>`}
function header(){const names={today:'Overview',diary:'Food Diary',recipes:'Recipes',training:'Training',progress:'Progress'};return `<header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Open menu" data-action="menu">${icon('menu',21)}</button><span>Your workspace</span>${icon('chevron',11)}<strong>${names[page]}</strong></div><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</span><button class="outline" data-action="goals">${icon('settings',13)}Edit my goals</button><button class="notification" aria-label="View daily reminder" data-action="reminder">${icon('bell',17)}</button></div></header>`}
function heading(title,desc,extra=''){return `<div class="heading"><div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
const goalBadge=()=>`<button class="goal-badge" data-action="goals">${icon('target',15)}<span>My goal:</span> <b>${goalNames[profile().goal]}</b>${icon('down',11)}</button>`;
function ringCard(){const t=totals(),g=targets(),left=Math.max(0,g.calories-t.calories),ratio=Math.min(1,t.calories/g.calories);return `<div class="card nutrition-card"><div class="card-title"><h3>Daily nutrition</h3><span class="small-label">${state.profile?'Your personal targets':'Example targets'} · Today</span></div><div class="nutrition-body"><div class="calorie-ring"><svg width="163" height="163" viewBox="0 0 163 163"><circle cx="81.5" cy="81.5" r="72" stroke="#f0f3e9" stroke-width="9" fill="none"/><circle cx="81.5" cy="81.5" r="72" stroke="#8fa96a" stroke-width="9" fill="none" stroke-dasharray="${ratio*452.4} 452.4" stroke-linecap="round"/></svg><div class="ring-center"><div class="cal-number">${format(t.calories)}</div><span>of ${format(g.calories)} kcal eaten</span><small>${icon('flame',10)} ${format(left)} kcal remaining</small></div></div><div class="macros">${[['protein','Protein','#d5ae7d'],['carbs','Carbs','#97adbf'],['fat','Fat','#b6a6cc']].map(([key,name,color])=>`<div class="macro"><div class="macro-label"><span class="macro-name"><i class="dot" style="background:${color}"></i>${name}</span><strong><b>${format(t[key])}</b> / ${g[key]} g</strong></div><div class="bar"><div style="width:${Math.min(100,t[key]/g[key]*100)}%;background:${color}"></div></div></div>`).join('')}</div></div><div class="nutrition-footer">${icon('leaf',12)}${state.profile?'Every balanced choice brings you a little closer.':'A balanced day starts here. Set your goals to personalize.'}</div></div>`}
function workoutCard(){const w=workout();return `<div class="workout-card"><div class="section-label">YOUR NEXT WORKOUT ${icon('dumbbell',15)}</div><div class="workout-tags"><span class="tag">Bodyweight</span><span class="tag">${w.level[0].toUpperCase()+w.level.slice(1)}</span></div><h2>${esc(w.title)}</h2><p>${w.isRecovery?'Make space for recovery. Your next step is a plan with a qualified professional.':'Build strength. Feel better.<br>One workout at a time.'}</p><div class="workout-visual">${athlete()}</div><div class="workout-meta"><span>${icon('clock',12)}${w.duration} min</span><span>${icon('dumbbell',12)}${w.exercises.length} exercises</span><span>${icon('heart',12)}No equipment</span></div><button class="btn full" data-action="${w.isRecovery?'training':'start-workout'}">${w.isRecovery?'View recovery guidance':'Let’s get moving'}${icon('arrow',13)}</button><div class="workout-footer">${w.requiresClearance?'Review movement limits with your clinician':'Made for your level. At your own pace.'}</div></div>`}
function waterCard(){const glasses=state.water[today()]||0;return `<div class="card water-card"><div class="card-title"><h3>A little hydration</h3><span style="color:#96b1b7">${icon('drop',19)}</span></div><div class="water-numbers"><strong>${(glasses*.25).toFixed(2).replace(/0$/,'')}<span style="font-size:13px;color:#789198">L</span></strong><span>/ 2 L daily guide</span></div><div class="water-glasses">${Array.from({length:8},(_,i)=>`<button class="glass ${i<glasses?'filled':''}" data-water="${i+1}" aria-label="Set water to ${(i+1)*250} milliliters"><svg width="23" height="28" viewBox="0 0 24 30" aria-hidden="true"><path d="M4 3h16l-2 23H6Z" fill="${i<glasses?'#b5cbd0':'#f3f6f2'}" stroke="currentColor" stroke-width="1.3"/><path d="M5 13c4-2 7 2 14 0" stroke="currentColor" stroke-width="1.3"/></svg></button>`).join('')}</div><button class="outline" data-action="water">${icon('plus',12)}Log a glass (250 ml)</button><div class="water-hint">Needs vary. Sip a little throughout your day.</div></div>`}
function mealsCard(){return `<div class="card meals-card"><div class="section-heading"><h2>On your plate today</h2><button class="text-link" data-page="diary">View diary ${icon('arrow',12)}</button></div>${Object.keys(mealIcons).map(meal=>{const logs=state.logs.filter(l=>l.date===today()&&l.meal===meal);return `<div class="meal-row"><span class="meal-icon">${icon(mealIcons[meal],18)}</span><div class="meal-info"><h4>${meal}</h4><p>${logs.length?esc(logs.map(l=>l.name).join(', ').slice(0,55)):'A fresh start. Add something delicious.'}</p></div><div class="meal-kcal">${format(logs.reduce((a,l)=>a+l.calories,0))}<span>kcal</span></div><button class="icon-btn" data-add-meal="${meal}" aria-label="Add ${meal.toLowerCase()}">${icon('plus',12)}</button></div>`}).join('')}</div>`}
const recipeImages={'chicken-bowl':'assets/hero.jpg','overnight-oats':'assets/recipe-oats.jpg','tuna-wrap':'assets/recipe-wrap.jpg','tofu-stirfry':'assets/recipe-bowl.jpg'};
function recipeCard(r){return `<button class="recipe-card" data-recipe="${r.id}"><img class="recipe-img" src="${recipeImages[r.id]||r.image}" alt="${esc(r.title)}" loading="lazy" onerror="this.src='assets/hero.jpg';this.onerror=null"><span class="recipe-price">~$${r.cost.toFixed(2)} / serving</span><div class="recipe-content"><div class="eyebrow">${esc(r.category)}</div><h3>${esc(r.title)}</h3><div class="recipe-meta"><span>${icon('clock',12)}${r.time} min</span><span>${icon('flame',12)}${r.calories} kcal</span><span class="protein">${r.protein} g protein</span></div></div></button>`}
function overview(){const name=state.profile?.name?.split(' ')[0];return `${heading(`Your everyday, a little healthier${name?`, ${esc(name)}`:'.'}`,'Good food, mindful movement, and a plan that fits your life.',goalBadge())}${quickActions()}<div class="dashboard-grid"><div class="left-col"><section class="hero"><div class="hero-copy"><div class="eyebrow">FUEL YOUR POTENTIAL</div><h2>Good food.<br>Stronger you.</h2><p>Eat well, move with purpose, and build habits that feel good.</p><button class="btn" data-action="add-food">${icon('plus',12)}Log your food${icon('arrow',12)}</button></div><img src="assets/hero.jpg" alt="A colorful, nourishing bowl of vegetables and chickpeas"></section><section><div class="section-label">YOUR DAILY SNAPSHOT</div>${ringCard()}</section>${mealsCard()}</div><div class="right-col">${workoutCard()}${waterCard()}<div class="tip-card"><div class="eyebrow">${icon('spark',14)}A LITTLE FOOD FOR THOUGHT</div><p>Healthy doesn’t have to be expensive. Beans, eggs, and seasonal veggies can go a long way.</p></div></div></div><section class="recipes-preview"><div class="section-heading"><div><h2>Feel-good food. Everyday prices.</h2><p style="font-size:10px;color:#99a28d;margin-top:6px">Simple ingredients. Balanced plates. Happy you.</p></div><button class="text-link" data-page="recipes">Explore recipes${icon('arrow',12)}</button></div><div class="recipe-grid">${[RECIPES[0],RECIPES[1],RECIPES[4]].map(recipeCard).join('')}</div></section>`}
function diary(){const t=totals(diaryDate),g=targets();return `${heading('Every bite, a little more mindful.','Your meals, portions, and daily nutrition in one place.',`<button class="btn" data-action="add-food">${icon('plus',13)}Add food</button>`)}<div class="page-toolbar"><span class="inline-label">Your food diary</span><input class="day-input" aria-label="Diary date" type="date" id="diary-date" value="${diaryDate}"><span class="inline-label">${state.sample?'Sample entries are marked below.':''}</span></div><div class="page-grid"><div>${Object.keys(mealIcons).map(meal=>{const logs=state.logs.filter(l=>l.date===diaryDate&&l.meal===meal);return `<div class="card diary-meal"><div class="section-heading"><h2>${icon(mealIcons[meal],16)} &nbsp; ${meal}</h2><button class="text-link" data-add-meal="${meal}">${icon('plus',12)}Add food</button></div>${logs.length?logs.map(l=>`<div class="food-line"><div class="food-main"><strong>${esc(l.name)}</strong><p>${esc(l.portion)}${l.sample?' · Sample entry':''}</p></div><span class="food-macros">P ${format(l.protein)} · C ${format(l.carbs)} · F ${format(l.fat)} g</span><span class="food-cals">${format(l.calories)}<small class="small-label"> kcal</small></span><button class="icon-btn" data-remove-log="${l.id}" aria-label="Remove ${esc(l.name)}">${icon('close',12)}</button></div>`).join(''):`<p class="inline-empty">Nothing logged yet. Your next good choice starts here.</p>`}</div>`}).join('')}</div><aside class="card summary-card"><h3>Your daily balance</h3>${[['Calories','calories','kcal'],['Protein','protein','g'],['Carbohydrates','carbs','g'],['Fats','fat','g']].map(([name,key,unit])=>`<div class="summary-row"><span>${name}</span><strong>${format(t[key])} <small style="font-weight:400;color:#9aa78e">/ ${g[key]} ${unit}</small></strong></div>`).join('')}<div class="notice">${g.calories>=t.calories?`${format(g.calories-t.calories)} kcal left in your daily guide.`:`${format(t.calories-g.calories)} kcal above today’s guide. One day doesn’t define your progress.`}</div><button class="btn light full" data-action="goals">${icon('target',14)}${state.profile?'Adjust my targets':'Personalize my targets'}</button><p class="summary-note">Food values are estimates. Use your product label when available. Water and food logs stay on this browser.</p></aside></div>`}
function recipes(){return `${heading('Good food. Within reach.','Affordable, balanced meals for real life. All nutrition is per serving.')}<div class="page-toolbar"><div class="search-field">${icon('search',17)}<input id="recipe-search" type="search" placeholder="Find your next favorite meal…" value="${esc(recipeQuery)}" aria-label="Search recipes"></div><div class="budget-control"><label for="recipe-budget">Budget per serving</label><select id="recipe-budget"><option value="5" ${budget==5?'selected':''}>Up to $5</option><option value="3" ${budget==3?'selected':''}>Up to $3</option><option value="2" ${budget==2?'selected':''}>Up to $2</option></select></div></div><div class="filters">${['All recipes','High protein','Plant based','Quick meals','Breakfast'].map(f=>`<button class="chip ${recipeFilter===f?'active':''}" data-recipe-filter="${f}">${f}</button>`).join('')}</div><div class="recipe-grid full-recipes" id="recipe-results">${filteredRecipes()}</div><p class="data-note" style="margin-top:20px">Prices are approximate USD estimates per serving; local prices vary. Photos are serving inspiration. Check ingredients for allergens.</p>`}
function filteredRecipes(){const list=RECIPES.filter(r=>r.cost<=budget&&`${r.title} ${r.ingredients.join(' ')}`.toLowerCase().includes(recipeQuery.toLowerCase())&&(recipeFilter==='All recipes'||recipeFilter==='High protein'&&r.protein>=25||recipeFilter==='Plant based'&&(['Plant based','Budget friendly'].includes(r.category))||recipeFilter==='Quick meals'&&r.time<=15||recipeFilter===r.category));return list.length?list.map(recipeCard).join(''):'<div class="card empty" style="grid-column:1/-1">No recipes match these filters. Try a larger budget or another category.</div>'}
function training(){const w=workout();return `${heading('Stronger, on your terms.','Bodyweight training that meets you where you are.',`<button class="outline" data-action="goals">${icon('settings',13)}Tailor my program</button>`)}<div class="training-intro">${workoutCard()}<div class="card"><div class="eyebrow">YOUR WEEK, WITH BALANCE</div><h2 style="font-size:22px;margin-top:10px;letter-spacing:-.5px">Consistency over intensity.</h2><p class="subheading" style="margin:10px 0 0">${w.isRecovery?'Recovery is productive, too.':'Three strength days. Room to recover. Progress at your pace.'}</p><div class="training-schedule">${['M','T','W','T','F','S','S'].map((d,i)=>`<div class="day-bubble ${!w.isRecovery&&[0,2,4].includes(i)?'active':''}">${d}<span>${icon(!w.isRecovery&&[0,2,4].includes(i)?'dumbbell':'leaf',13)}</span></div>`).join('')}</div><ul class="info-list"><li>${icon('check',15)}${esc(w.warmup)}</li><li>${icon('check',15)}${esc(w.progression)}</li></ul></div></div>${shoulderGuidance()}<div class="notice">${esc(w.note)} ${w.requiresClearance?'This program is a movement filter, not an injury assessment or rehabilitation plan.':''}</div><div class="card"><div class="section-heading"><h2>${w.isRecovery?'Your next step':'Your full-body session'}</h2><span class="small-label">${w.exercises.length} exercises · ${w.duration} minutes</span></div>${w.exercises.length?w.exercises.map((e,i)=>`<div class="exercise-row"><span class="exercise-no">${String(i+1).padStart(2,'0')}</span><div class="exercise-text"><h3>${esc(e.name)}</h3><p>${esc(e.instructions)}</p></div><span class="exercise-dose">${e.sets} × ${e.reps}<br><small class="small-label">${e.rest}s rest / set</small></span></div>`).join(''):`<div class="empty">${icon('heart',30)}<p>Rest or choose activity that your clinician has cleared.<br>Update your movement preferences when you have guidance.</p></div>`}</div><p class="privacy-note">A structured starting program, tailored with rules for experience and selected limitations. It cannot guarantee fat loss, muscle gain, or injury safety.</p>`}
function progress(){const weights=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date));const logged=new Set(state.logs.filter(l=>!l.sample).map(l=>l.date)).size;return `${heading('Small steps add up.','A little perspective on the habits you’re building.',`<button class="btn" data-action="log-weight">${icon('plus',13)}Log weight</button>`)}<div class="progress-grid"><div class="stat-tile"><span>${icon('calendar',14)} &nbsp; Days with food logged</span><strong>${logged}</strong><small>Your personal entries, excluding the sample day.</small></div><div class="stat-tile"><span>${icon('dumbbell',14)} &nbsp; Workouts completed</span><strong>${state.sessions.length}</strong><small>Every session is a step forward.</small></div><div class="card chart-card"><div class="section-heading"><h2>Your weight, over time</h2><span class="small-label">${weights.length?`Latest: ${weights.at(-1).weight} kg`:'No entries yet'}</span></div>${weights.length?weightChart(weights):`<div class="empty" style="padding:65px 20px">${icon('chart',32)}<p>Your story starts with one entry.<br>Log your weight whenever it feels helpful.</p></div>`}<div class="weight-list">${weights.slice(-5).reverse().map(w=>`<div class="weight-row"><span>${new Date(w.date+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</span><strong>${w.weight} kg &nbsp;<button class="text-link" data-remove-weight="${w.id}" aria-label="Remove weight entry">${icon('close',12)}</button></strong></div>`).join('')}</div></div><div class="card chart-card"><h3 style="font-size:14px;margin-bottom:10px">Your recent movement</h3>${state.sessions.length?state.sessions.slice(-5).reverse().map(s=>`<div class="weight-row"><span>${esc(s.title)}</span><span>${new Date(s.date).toLocaleDateString()}</span></div>`).join(''):'<p class="subheading" style="margin:0">Your completed workouts will appear here. A fresh start is a good place to be.</p>'}</div></div>`}
function weightChart(ws){const W=800,H=190,pad=25,vals=ws.map(w=>w.weight),min=Math.min(...vals)-1,max=Math.max(...vals)+1;const points=ws.map((w,i)=>`${ws.length===1?400:pad+i/(ws.length-1)*(W-2*pad)},${H-pad-(w.weight-min)/(max-min)*(H-2*pad)}`);return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Weight chart: ${ws.map(w=>`${w.weight} kilograms on ${w.date}`).join(', ')}">${[0,.5,1].map(v=>`<line x1="25" x2="775" y1="${pad+v*(H-2*pad)}" y2="${pad+v*(H-2*pad)}" stroke="#edf1e6"/>`).join('')}<polyline points="${points.join(' ')}" fill="none" stroke="#8da76d" stroke-width="3"/>${points.map((p,i)=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="5" fill="#6e8e50"><title>${ws[i].date}: ${ws[i].weight} kg</title></circle>`).join('')}</svg>`}
function footer(){return `<footer class="page-footer"><span>Made for progress, not perfection. ${icon('leaf',10)}</span>${state.sample?`<div class="sample-tag">You’re exploring a sample day.<button data-action="clear-sample">Start my own day ${icon('arrow',10)}</button></div>`:`<span>Saved on this device · A little better, every day.</span>`}</footer>`}
function mobileNav(){return `<nav class="bottom-nav" aria-label="Mobile navigation">${[['today','grid','Home'],['diary','book','Diary'],['recipes','utensils','Recipes'],['training','dumbbell','Train'],['progress','chart','Progress']].map(([id,i,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i,19)}<span>${label}</span></button>`).join('')}</nav>`}
function quickActions(){return `<section class="quick-actions" aria-label="Quick actions"><button data-action="add-food">${icon('plus',18)}<span>Log food</span></button><button data-action="water">${icon('drop',18)}<span>Add water</span></button><button data-action="log-weight">${icon('chart',18)}<span>Log weight</span></button><button data-page="training">${icon('dumbbell',18)}<span>My training</span></button></section>`}
function shoulderGuidance(){return `<section class="card shoulder-guide"><div class="eyebrow">SHOULDER-CONSCIOUS TRAINING</div><h2>Protect first. Build progressively.</h2><p>With painful proximal biceps or labral injuries and unknown exercise clearance, do not begin upper-body loading based on an app-generated plan. Ask your orthopedic clinician or physical therapist about your PRP protocol and approved movements.</p><div class="shoulder-steps"><div><strong>Stage 1 · Assessment</strong><span>Clarify restrictions, pain triggers and approved daily movement.</span></div><div><strong>Stage 2 · Guided activation</strong><span>Only if cleared: therapist-selected range of motion and gentle stabilizer work.</span></div><div><strong>Stage 3 · Gradual strength</strong><span>Only when cleared: progressive chest, back, shoulder and arm loading.</span></div></div><p class="shoulder-caution">Avoid push-ups, planks, dips, pull-ups, resisted curls and overhead loading until your treating clinician permits them. Stop activities that worsen pain.</p></section>`}
function render(){const pages={today:overview,diary,recipes,training,progress};$('#app').innerHTML=`${navigation()}<div class="shell">${header()}<main class="content" id="main-content">${pages[page]()}${footer()}</main></div>${mobileNav()}`}
function navigate(to){page=to;render();window.scrollTo({top:0,behavior:'instant'})}
function openModal(title,body,wide=false){if(!$('#modal-root').firstChild)modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close-btn" data-action="close" aria-label="Close dialog">${icon('close',16)}</button></div><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';$('#app').inert=true;setTimeout(()=>$('.modal input:not([type=checkbox]),.modal select,.modal .btn,.modal .close-btn')?.focus(),30)}
function closeModal(){clearInterval(restTimer);restTimer=null;session=null;$('#modal-root').innerHTML='';document.body.style.overflow='';$('#app').inert=false;modalReturnFocus?.isConnected&&modalReturnFocus.focus()}
function goalsModal(){const p=state.profile||{name:'',age:30,sex:'female',weight:70,height:170,activity:'moderate',goal:'lose',experience:'beginner',limitations:[]};openModal('A plan that feels like you.',`<p class="modal-desc">A few details help estimate your daily fuel and shape a bodyweight routine. You can change these anytime.</p><form id="goals-form"><div class="form-grid"><div class="field full"><label for="goal-name">What should we call you?</label><input id="goal-name" name="name" maxlength="35" placeholder="Your first name" value="${esc(p.name)}"></div><div class="field full"><label for="goal-choice">Your main goal</label><select id="goal-choice" name="goal">${Object.entries(goalNames).map(([v,l])=>`<option value="${v}" ${p.goal===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="goal-age">Age (18–100)</label><input id="goal-age" type="number" name="age" min="18" max="100" required value="${p.age}"></div><div class="field"><label for="goal-sex">Sex used in calorie equation</label><select id="goal-sex" name="sex"><option value="female" ${p.sex==='female'?'selected':''}>Female</option><option value="male" ${p.sex==='male'?'selected':''}>Male</option></select><small>A physiological input for this estimate.</small></div><div class="field"><label for="goal-weight">Weight (kg)</label><input id="goal-weight" type="number" name="weight" min="35" max="300" step=".1" required value="${p.weight}"></div><div class="field"><label for="goal-height">Height (cm)</label><input id="goal-height" type="number" name="height" min="120" max="230" step=".1" required value="${p.height}"></div><div class="field full"><label for="goal-activity">Typical activity, including exercise</label><select id="goal-activity" name="activity">${[['sedentary','Mostly seated · little exercise'],['light','Light · 1–3 active days a week'],['moderate','Moderate · 3–5 active days a week'],['active','Very active · 6–7 active days a week']].map(([v,l])=>`<option value="${v}" ${p.activity===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="goal-experience">Your training experience</label><select id="goal-experience" name="experience">${['beginner','intermediate','advanced'].map(x=>`<option ${p.experience===x?'selected':''} value="${x}">${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></div><div class="field full"><span>Movement limitations to work around</span><div class="checkboxes">${['knee','back','wrist','shoulder','other'].map(x=>`<label class="check-label"><input name="limitations" type="checkbox" value="${x}" ${p.limitations?.includes(x)?'checked':''}>${x[0].toUpperCase()+x.slice(1)}</label>`).join('')}</div><small>Selected areas exclude potentially aggravating exercises. An injury needs individual assessment; confirm a modified routine with your clinician.</small></div></div><div class="notice">Calorie and macro targets use Mifflin–St Jeor, a moderate goal adjustment, 1.8 g protein/kg and 0.8 g fat/kg. These are starting estimates for generally healthy adults, not for pregnancy, breastfeeding, or eating-disorder recovery.</div><div id="goal-error" class="error" role="alert"></div><div class="form-footer"><button class="btn" type="submit">Build my personal plan ${icon('arrow',14)}</button></div><p class="privacy-note">Your profile is stored in this browser. It is not synced to other devices. Clear browsing data to remove it, or manage your data in Help.</p></form>`,true)}
function foodModal(meal='Breakfast'){foodMeal=meal;foodQuery='';foodTab='catalog';foodResults=[...FOODS,...state.customFoods];openModal('A little fuel for your day.',`<div class="tabs"><button class="active" data-food-tab="catalog">Food catalog</button><button data-food-tab="world">Packaged food search</button><button data-food-tab="custom">Custom food</button></div><div id="food-tab-content"></div>`);foodTabContent()}
function foodTabContent(){const root=$('#food-tab-content');if(!root)return;if(foodTab==='custom'){root.innerHTML=`<p class="modal-desc">Copy the values from your label. Nutrition below is for 100 g, so any portion can be logged accurately.</p><form id="custom-food-form"><div class="form-grid"><div class="field full"><label for="custom-name">Food name</label><input name="name" id="custom-name" required maxlength="100" placeholder="e.g. My favorite granola"></div>${[['calories','Calories (kcal)'],['protein','Protein (g)'],['carbs','Carbs (g)'],['fat','Fat (g)']].map(([k,l])=>`<div class="field"><label for="custom-${k}">${l} / 100 g</label><input id="custom-${k}" name="${k}" type="number" min="0" max="${k==='calories'?1000:100}" step=".1" required></div>`).join('')}</div><div class="form-footer"><button class="btn" type="submit">Save & choose a portion ${icon('arrow',13)}</button></div></form>`;return}root.innerHTML=`<p class="modal-desc">${foodTab==='world'?'Search Open Food Facts for packaged foods worldwide. Community data may be incomplete; compare with the label.':'Browse 85 everyday ingredients, drinks, whole foods, and restaurant estimates. Each includes food-specific portions.'}</p><form id="food-search-form" class="page-toolbar" style="margin-bottom:10px"><div class="search-field">${icon('search',16)}<input id="food-search" type="search" placeholder="${foodTab==='world'?'Search a product or brand…':'Try oats, chicken, coffee…'}" aria-label="Search food" value="${esc(foodQuery)}" minlength="${foodTab==='world'?2:0}"></div>${foodTab==='world'?'<button class="btn" type="submit">Search</button>':''}</form><div class="food-results" id="food-results"></div><div class="data-note">${foodTab==='world'?'Source: Open Food Facts · Open Database License. Searches are sent to world.openfoodfacts.org.':'Approximate reference values, not an exhaustive database. Restaurant recipes and serving sizes vary. Check your local menu.'}</div>`;renderFoodResults(foodTab==='world'?[]:foodResults);}
function renderFoodResults(list){const el=$('#food-results');if(!el)return;el.innerHTML=list.length?list.slice(0,70).map(f=>`<button class="food-result" data-food-id="${esc(f.id)}"><span class="meal-icon">${icon(f.category==='Drinks'?'drop':'apple',16)}</span><div class="food-main"><strong>${esc(f.name)}</strong><p>${esc(f.brand)} · ${esc(f.category||'Packaged food')}</p></div><span>${format(f.calories)} kcal<small style="display:block;font-size:8px;color:#a1aa95;margin-top:4px">per 100 g</small></span>${icon('plus',14)}</button>`).join(''):`<div class="empty">${foodTab==='world'?'Enter a product name, then select Search.':'No foods found. Try a different word or add a custom food.'}</div>`}
let searchSequence=0;
async function searchWorld(){const query=$('#food-search')?.value.trim();if(!query||query.length<2)return;foodQuery=query;const seq=++searchSequence;$('#food-results').innerHTML='<div class="empty">Searching Open Food Facts…</div>';try{const fields='code,product_name,brands,nutriments,serving_quantity';const url=`https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(query)}&search_simple=1&action=process&json=1&page_size=24&fields=${fields}`;const res=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error();const data=await res.json();if(seq!==searchSequence||foodTab!=='world'||!$('#food-results'))return;foodResults=(data.products||[]).filter(p=>p.product_name&&['energy-kcal_100g','proteins_100g','carbohydrates_100g','fat_100g'].every(k=>Number.isFinite(Number(p.nutriments?.[k]))&&p.nutriments[k]!=null&&Number(p.nutriments[k])>=0&&Number(p.nutriments[k])<=(k==='energy-kcal_100g'?1000:100))).map(p=>({id:`off-${p.code}`,name:p.product_name,brand:p.brands||'Open Food Facts',category:'Packaged food',calories:Number(p.nutriments['energy-kcal_100g']),protein:Number(p.nutriments.proteins_100g),carbs:Number(p.nutriments.carbohydrates_100g),fat:Number(p.nutriments.fat_100g),source:'Open Food Facts · community-contributed. Confirm with product label.',servings:[{label:'100 g',grams:100},{label:'1 g',grams:1},...(Number(p.serving_quantity)>0?[{label:`Label serving (${p.serving_quantity} g)`,grams:Number(p.serving_quantity)}]:[])]}));renderFoodResults(foodResults);if(!foodResults.length)$('#food-results').innerHTML='<div class="empty">No complete nutrition matches found. Try a brand name, or create a custom entry from the label.</div>';}catch{if(seq===searchSequence&&foodTab==='world'&&$('#food-results'))$('#food-results').innerHTML='<div class="empty">Packaged-food search is unavailable right now. You can still use the catalog or add nutrition from a label.<br><button class="text-link" data-action="retry-food">Try again</button></div>';}}
function portionModal(food){selectedFood=food;const serving=food.servings.length>2?2:0;openModal('Make it your portion.',`<button class="text-link" data-action="back-food">${icon('back',12)}Back to food search</button><h3 style="font-size:19px;margin:18px 0 6px">${esc(food.name)}</h3><p class="modal-desc">${esc(food.brand)} · ${esc(food.source)}</p><form id="portion-form"><div class="form-grid"><div class="field"><label for="portion-qty">Quantity</label><input id="portion-qty" name="quantity" type="number" min=".01" max="10000" step=".01" required value="1"></div><div class="field"><label for="portion-unit">Serving size</label><select id="portion-unit" name="serving">${food.servings.map((s,i)=>`<option value="${i}" ${i===serving?'selected':''}>${esc(s.label)}${!['100 g','1 g'].includes(s.label)?` (~${s.grams} g)`:''}</option>`).join('')}</select></div><div class="field"><label for="portion-meal">Add to meal</label><select id="portion-meal" name="meal">${Object.keys(mealIcons).map(m=>`<option ${m===foodMeal?'selected':''}>${m}</option>`).join('')}</select></div><div class="field"><label for="portion-date">Date</label><input id="portion-date" name="date" type="date" required value="${page==='diary'?diaryDate:today()}"></div></div><div id="portion-preview"></div><div class="form-footer"><button class="btn" type="submit">${icon('plus',13)}Add to food diary</button></div></form>`);updatePortion()}
function updatePortion(){if(!selectedFood||!$('#portion-qty'))return;const amount=Number($('#portion-qty').value)||0;const grams=selectedFood.servings[Number($('#portion-unit').value)].grams*amount;$('#portion-preview').innerHTML=`<div class="serving-preview">${[['calories','kcal'],['protein','Protein · g'],['carbs','Carbs · g'],['fat','Fat · g']].map(([k,l])=>`<div><strong>${format(selectedFood[k]*grams/100)}</strong><small>${l}</small></div>`).join('')}</div><p class="data-note">Total portion: ${Math.round(grams*10)/10} g · Cup and spoon conversions are specific to this food.</p>`}
function recipeModal(id){const r=RECIPES.find(r=>r.id===id);openModal(esc(r.title),`<img class="recipe-detail-img" src="${recipeImages[r.id]||r.image}" alt="${esc(r.title)}" onerror="this.src='assets/hero.jpg';this.onerror=null"><p class="modal-desc" style="margin-top:20px">${esc(r.description)}</p><div class="recipe-detail-meta"><span>${icon('clock',12)} ${r.time} min</span><span>~$${r.cost.toFixed(2)} / serving</span><span>${r.calories} kcal / serving</span><span>${r.protein} g protein</span><span>${r.carbs} g carbs</span><span>${r.fat} g fat</span></div><section class="recipe-section"><h3>What you’ll need · makes ${r.servings} serving${r.servings>1?'s':''}</h3><ul>${r.ingredients.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></section><section class="recipe-section"><h3>Let’s make it</h3><ol>${r.steps.map(i=>`<li>${esc(i)}</li>`).join('')}</ol></section><div class="notice">Nutrition and price are estimates per serving. Ingredient amounts above make the full recipe. Photos are serving inspiration. Check allergens before preparing.</div><div class="field" style="margin-bottom:17px"><label for="recipe-meal">Log one serving to</label><select id="recipe-meal">${Object.keys(mealIcons).map(m=>`<option ${m==='Lunch'?'selected':''}>${m}</option>`).join('')}</select></div><div class="recipe-actions"><button class="btn light" data-shopping="${r.id}">${icon('download',13)}Shopping list</button><button class="btn" data-log-recipe="${r.id}">${icon('plus',13)}Log 1 serving</button></div>`)}
function startWorkout(){const w=workout();if(w.isRecovery){navigate('training');return}openModal('Make room for movement.',`<div class="session-focus">${athlete()}<h3>${esc(w.title)}</h3><p class="modal-desc" style="margin-top:13px">${w.exercises.length} exercises · ${w.duration} minutes · ${w.level}</p></div><div class="notice">${esc(w.warmup)}<br><br>${esc(w.note)}</div>${w.requiresClearance?'<label class="check-label" style="margin-bottom:20px!important"><input type="checkbox" id="workout-clearance">I have reviewed these exercises with my clinician and have clearance to do them.</label>':''}<button class="btn full" data-action="begin-session">I’m warmed up. Let’s start ${icon('arrow',14)}</button><p class="privacy-note">This is a guided checklist, not a timed fitness assessment. Stop any exercise that hurts. Rest between every set.</p>`)}
function renderSession(){const s=session,e=s.workout.exercises[s.index];const rest=s.resting;openModal('Your time to get stronger.',`<div class="session-stepbar">${s.workout.exercises.map((_,i)=>`<span class="${i<s.index?'done':''}"></span>`).join('')}</div><div class="session-focus"><div class="eyebrow">EXERCISE ${s.index+1} OF ${s.workout.exercises.length} · SET ${s.set} OF ${e.sets}</div><h3>${esc(e.name)}</h3><div class="session-dose">${rest?'Breathe. Recover.':esc(e.reps)+(/seconds|repetitions/.test(e.reps)?'':' reps')}</div><p class="session-instructions">${esc(e.instructions)}</p>${rest?`<div class="session-timer" id="rest-seconds">${s.restRemaining}s</div>`:''}</div><div class="session-actions"><button class="btn light" data-action="end-session">End session</button><button class="btn" data-action="${rest?'finish-rest':'finish-set'}">${rest?'Continue when ready':'Set complete'}${icon('check',14)}</button></div><p class="privacy-note">Rest ${e.rest} seconds between sets. Keep 2–3 repetitions in reserve. Move only through a comfortable range.</p>`)}
function finishSet(){if(!session)return;session.completedSets++;session.resting=true;session.restRemaining=session.workout.exercises[session.index].rest;renderSession();restTimer=setInterval(()=>{if(!session){clearInterval(restTimer);return}session.restRemaining=Math.max(0,session.restRemaining-1);if($('#rest-seconds'))$('#rest-seconds').textContent=session.restRemaining?`${session.restRemaining}s`:'Ready when you are';if(!session.restRemaining)clearInterval(restTimer)},1000)}
function nextSet(){clearInterval(restTimer);restTimer=null;const e=session.workout.exercises[session.index];if(session.set<e.sets){session.set++}else{session.index++;session.set=1}if(session.index>=session.workout.exercises.length){const s=session;state.sessions.push({id:uid(),date:new Date().toISOString(),title:s.workout.title,sets:s.completedSets});save();session=null;openModal('You showed up. That matters.',`<div class="session-focus"><div class="success-icon">${icon('check',30)}</div><h3>One session stronger.</h3><p class="modal-desc" style="margin-top:17px">${s.workout.exercises.length} exercises. ${s.completedSets} sets.<br>Take a breath, have some water, and give yourself time to recover.</p><button class="btn full" data-action="finish-workout">Back to my day ${icon('arrow',14)}</button></div>`);render();return}session.resting=false;renderSession()}
function weightModal(){openModal('One point in your progress.',`<p class="modal-desc">Daily fluctuations are normal. A longer trend is more useful than one measurement.</p><form id="weight-form"><div class="form-grid"><div class="field"><label for="weight-value">Weight (kg)</label><input name="weight" id="weight-value" type="number" min="25" max="350" step=".1" required placeholder="70.0"></div><div class="field"><label for="weight-date">Date</label><input name="date" id="weight-date" type="date" required max="${today()}" value="${today()}"></div></div><div class="form-footer"><button class="btn" type="submit">Save my entry ${icon('check',14)}</button></div></form>`)}
function about(){openModal('A little more about Nourish.',`<p class="modal-desc">Your food, movement, and goals — together in one calm space.</p><section class="recipe-section"><h3>Your data stays here</h3><p class="data-note">Profiles, food logs, water, weights, and workout history are stored in this browser’s local storage. There is no account or cross-device sync. You can export a backup below.</p></section><section class="recipe-section"><h3>Food information</h3><p class="data-note">The built-in catalog contains 85 approximate reference foods, including restaurant estimates. It is not exhaustive or independently verified. Packaged-food search uses community-contributed Open Food Facts data under the Open Database License (ODbL). Compare values with your label. Food photos are from Unsplash and show serving inspiration.</p></section><section class="recipe-section"><h3>Targets & movement</h3><p class="data-note">Targets use Mifflin–St Jeor and a moderate calorie adjustment, with 1.8 g protein/kg and 0.8 g fat/kg. Training uses rules for level and movement exclusions. Estimates cannot assess an injury; review modifications with your clinician. For generally healthy adults, 18+. Not designed for pregnancy, breastfeeding, or eating-disorder recovery.</p></section><div class="recipe-actions"><button class="btn light" data-action="export">${icon('download',14)}Export my data</button><button class="btn" data-action="goals">${icon('target',14)}My personal plan</button></div><button class="danger-link" data-action="reset-dialog">Clear all my data</button>`)}
function downloadFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function clearSample(){state.logs=state.logs.filter(l=>!l.sample);state.sample=false;state.water[today()]=0;save();render();toast('A fresh start. Your day is ready for you.')}
// Event delegation keeps all navigation, dynamically rendered dialogs, and cards interactive.
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-page],.mobile-overlay');if(!el)return;if(el.dataset.page){closeModal();navigate(el.dataset.page);return}if(el.classList.contains('mobile-overlay')){$('.sidebar').classList.remove('open');el.classList.remove('visible');return}if(el.dataset.addMeal){foodModal(el.dataset.addMeal);return}if(el.dataset.water){state.water[today()]=Number(el.dataset.water);save();render();return}if(el.dataset.recipe){recipeModal(el.dataset.recipe);return}if(el.dataset.recipeFilter){recipeFilter=el.dataset.recipeFilter;render();return}if(el.dataset.removeLog){state.logs=state.logs.filter(l=>l.id!==el.dataset.removeLog);save();render();toast('Food removed from your diary.');return}if(el.dataset.removeWeight){state.weights=state.weights.filter(w=>w.id!==el.dataset.removeWeight);save();render();return}if(el.dataset.foodTab){foodTab=el.dataset.foodTab;searchSequence++;$$('[data-food-tab]').forEach(b=>b.classList.toggle('active',b.dataset.foodTab===foodTab));foodQuery='';foodResults=[...FOODS,...state.customFoods];foodTabContent();return}if(el.dataset.foodId){const food=foodResults.find(f=>f.id===el.dataset.foodId);if(food)portionModal(food);return}if(el.dataset.logRecipe){const r=RECIPES.find(r=>r.id===el.dataset.logRecipe),meal=$('#recipe-meal').value;state.logs.push({id:uid(),name:r.title,meal,calories:r.calories,protein:r.protein,carbs:r.carbs,fat:r.fat,portion:'1 serving',date:page==='diary'?diaryDate:today()});save();closeModal();render();toast(`${r.title} added to ${meal.toLowerCase()}.`);return}if(el.dataset.shopping){const r=RECIPES.find(r=>r.id===el.dataset.shopping);downloadFile(`nourish-${r.id}-shopping.txt`,`${r.title}\nMakes ${r.servings} servings · Approx. $${r.cost.toFixed(2)}/serving\n\n${r.ingredients.map(i=>'☐ '+i).join('\n')}\n\nNutrition per serving (estimated): ${r.calories} kcal · P ${r.protein} g · C ${r.carbs} g · F ${r.fat} g`,'text/plain');toast('Shopping list downloaded.');return}switch(el.dataset.action){case'menu':$('.sidebar').classList.toggle('open');$('.mobile-overlay').classList.toggle('visible');break;case'goals':goalsModal();break;case'add-food':foodModal();break;case'close':closeModal();break;case'about':about();break;case'reminder':toast('A little reminder: fuel yourself, take a water break, and move at your own pace.');break;case'clear-sample':clearSample();break;case'water':state.water[today()]=Math.min(40,(state.water[today()]||0)+1);save();render();toast('One glass logged. A little refresh goes a long way.');break;case'retry-food':searchWorld();break;case'back-food':foodModal(foodMeal);break;case'training':navigate('training');break;case'start-workout':startWorkout();break;case'begin-session':if(workout().requiresClearance&&!$('#workout-clearance')?.checked){toast('Please confirm your clinician has cleared this routine.');return}session={workout:workout(),index:0,set:1,completedSets:0,resting:false};renderSession();break;case'finish-set':finishSet();break;case'finish-rest':nextSet();break;case'end-session':closeModal();toast('Session ended. Listen to your body; you can return anytime.');break;case'finish-workout':closeModal();navigate('today');break;case'log-weight':weightModal();break;case'export':downloadFile('nourish-data.json',JSON.stringify(state,null,2),'application/json');toast('Your data backup has been downloaded.');break;case'reset-dialog':openModal('A fresh start?',`<p class="modal-desc">This removes your profile, diary, water logs, weight entries, custom foods, and workout history from this browser. Export a backup first if you’d like to keep them.</p><div class="recipe-actions"><button class="btn light" data-action="close">Keep my data</button><button class="btn" data-action="reset-all">Clear my data</button></div>`);break;case'reset-all':state={profile:null,logs:[],water:{},weights:[],sessions:[],customFoods:[],sample:false};save();closeModal();navigate('today');toast('Your data has been cleared. A fresh start is ready.');break;}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='recipe-search'){recipeQuery=el.value;$('#recipe-results').innerHTML=filteredRecipes()}if(el.id==='food-search'&&foodTab==='catalog'){foodQuery=el.value;foodResults=[...FOODS,...state.customFoods].filter(f=>`${f.name} ${f.brand} ${f.category}`.toLowerCase().includes(foodQuery.toLowerCase()));renderFoodResults(foodResults)}if(['portion-qty','portion-unit'].includes(el.id))updatePortion()});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='diary-date'&&el.value){diaryDate=el.value;render()}if(el.id==='recipe-budget'){budget=Number(el.value);$('#recipe-results').innerHTML=filteredRecipes()}if(el.id==='portion-unit')updatePortion()});
document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();const d=new FormData(form);if(form.id==='goals-form'){try{const p={name:d.get('name').trim(),age:Number(d.get('age')),sex:d.get('sex'),weight:Number(d.get('weight')),height:Number(d.get('height')),activity:d.get('activity'),goal:d.get('goal'),experience:d.get('experience'),limitations:d.getAll('limitations')};const t=calculateTargets(p);state.profile=p;save();closeModal();render();toast(`Your plan is ready: ~${format(t.calories)} kcal · ${t.protein} g protein daily.`)}catch(e){$('#goal-error').textContent=e.message}}else if(form.id==='food-search-form'){if(foodTab==='world')searchWorld()}else if(form.id==='custom-food-form'){const food={id:'custom-'+uid(),name:d.get('name').trim(),brand:'Your custom food',category:'Custom',calories:Number(d.get('calories')),protein:Number(d.get('protein')),carbs:Number(d.get('carbs')),fat:Number(d.get('fat')),source:'Custom nutrition entered from your label.',servings:[{label:'100 g',grams:100},{label:'1 g',grams:1},{label:'1 oz',grams:28.35}]};if(!food.name)return;state.customFoods.push(food);save();portionModal(food)}else if(form.id==='portion-form'){const amount=Number(d.get('quantity')),serving=selectedFood.servings[Number(d.get('serving'))],factor=amount*serving.grams/100;if(!(factor>0))return;state.logs.push({id:uid(),name:selectedFood.name,meal:d.get('meal'),date:d.get('date'),portion:`${amount} × ${serving.label} (${Math.round(factor*1000)/10} g)`,...Object.fromEntries(['calories','protein','carbs','fat'].map(k=>[k,Math.round(selectedFood[k]*factor*10)/10]))});save();closeModal();render();toast('Food added. One small step, logged.')}else if(form.id==='weight-form'){const date=d.get('date'),weight=Number(d.get('weight'));if(!date||date>today()||weight<25||weight>350)return;state.weights=state.weights.filter(w=>w.date!==date);state.weights.push({id:uid(),date,weight});save();closeModal();render();toast('Your weight entry is saved.')}});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal)return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focusable=$$('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href]',modal);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
